<?php

declare(strict_types=1);

namespace DDD\Domain\AI\Entities\MediaItems;

/**
 * The EU AI Act label a published image carries: "generated by AI" or "edited with AI". An image that needs no label
 * has no variant.
 *
 * Its own type because the image stamper and the labelled copy of an image use it without the label policy. The values
 * end up in the storage key of the labelled copy and in the claim of the token that serves it, so they never change.
 */
class AIImageLabelVariant
{
    /** @var string The label of an image an AI model produced */
    public const string GENERATED = 'GENERATED';

    /** @var string The label of the customer's own image, changed with an AI editor */
    public const string EDITED = 'EDITED';

    /** @var string[] Every label variant */
    public const array ALL_VARIANTS = [
        self::GENERATED,
        self::EDITED,
    ];
}
